namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain any leftover items from the static queue
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain after each test to avoid cross-test pollution
            while (_sut.ReceiveNotification() != null) { }
            _sut.Dispose();
        }

        // ── SendNotification + ReceiveNotification round-trip ──

        [Fact]
        public void SendNotification_Create_ProducesCorrectMessage()
        {
            _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
            Assert.Equal("System", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_Update_ProducesCorrectMessage()
        {
            _sut.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
            Assert.Equal("UPDATE", notification.Operation);
        }

        [Fact]
        public void SendNotification_Delete_ProducesCorrectMessage()
        {
            _sut.SendNotification("Department", "7", "Engineering", EntityOperation.DELETE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
            Assert.Equal("DELETE", notification.Operation);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            _sut.SendNotification("Student", "99", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithNullDisplayName_UsesIdInMessage()
        {
            _sut.SendNotification("Student", "99", null, EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 99) has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithUserName_SetsCreatedBy()
        {
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "admin@test.com");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("admin@test.com", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToApproximatelyNow()
        {
            var before = DateTime.Now;
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            var after = DateTime.Now;

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        // ── ReceiveNotification ──

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_FifoOrder()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void ReceiveNotification_DequeuesItem_SecondCallReturnsNull()
        {
            _sut.SendNotification("X", "1", EntityOperation.CREATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Null(second);
        }

        // ── Queue cap enforcement ──

        [Fact]
        public void SendNotification_ExceedingMaxQueueLength_OldestItemsRemoved()
        {
            // Enqueue 510 items; the cap is 500 so the oldest should be trimmed
            for (int i = 0; i < 510; i++)
            {
                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Count remaining items
            int count = 0;
            while (_sut.ReceiveNotification() != null) count++;

            Assert.True(count <= 500, $"Expected at most 500 items but found {count}");
        }

        // ── GenerateMessage (tested indirectly) ──

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Course 'Math' has been created")]
        [InlineData(EntityOperation.UPDATE, "Course 'Math' has been updated")]
        [InlineData(EntityOperation.DELETE, "Course 'Math' has been deleted")]
        public void SendNotification_GenerateMessage_CorrectTextForEachOperation(EntityOperation op, string expected)
        {
            _sut.SendNotification("Course", "1", "Math", op);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal(expected, notification.Message);
        }

        [Fact]
        public void SendNotification_WhitespaceDisplayName_UsesIdFallback()
        {
            _sut.SendNotification("Student", "5", "   ", EntityOperation.DELETE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 5) has been deleted", notification.Message);
        }

        // ── Dispose ──

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _sut.MarkAsRead(1));

            Assert.Null(exception);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedStudents()
        {
            _context.Students.AddRange(
                new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
                new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
                new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") }
            );
            _context.SaveChanges();
        }

        // ── Index ──

        [Fact]
        public void Index_NoSortOrFilter_ReturnsStudentsOrderedByLastName()
        {
            SeedStudents();

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal(3, model.Count);
            Assert.Equal("Alexander", model[0].LastName);
            Assert.Equal("Alonso", model[1].LastName);
            Assert.Equal("Anand", model[2].LastName);
        }

        [Fact]
        public void Index_NameDesc_SortsDescending()
        {
            SeedStudents();

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal("Anand", model[0].LastName);
            Assert.Equal("Alonso", model[1].LastName);
            Assert.Equal("Alexander", model[2].LastName);
        }

        [Theory]
        [InlineData("Date")]
        [InlineData("date_desc")]
        public void Index_DateSort_SortsByEnrollmentDate(string sortOrder)
        {
            SeedStudents();

            var result = _controller.Index(sortOrder, null, null, null) as ViewResult;

            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal(3, model.Count);
            if (sortOrder == "Date")
            {
                Assert.Equal("Alexander", model[0].LastName); // 2010
                Assert.Equal("Alonso", model[1].LastName);    // 2012
                Assert.Equal("Anand", model[2].LastName);     // 2013
            }
            else
            {
                Assert.Equal("Anand", model[0].LastName);     // 2013
                Assert.Equal("Alonso", model[1].LastName);    // 2012
                Assert.Equal("Alexander", model[2].LastName); // 2010
            }
        }

        [Fact]
        public void Index_SearchString_FiltersByName()
        {
            SeedStudents();

            var result = _controller.Index(null, null, "Al", null) as ViewResult;

            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
            Assert.All(model, s => Assert.True(
                s.LastName.Contains("Al") || s.FirstMidName.Contains("Al")));
        }

        [Fact]
        public void Index_SearchStringNull_UsesCurrentFilter()
        {
            SeedStudents();

            var result = _controller.Index(null, "Anand", null, null) as ViewResult;

            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Anand", model[0].LastName);
        }

        [Fact]
        public void Index_NewSearchString_ResetsPageTo1()
        {
            SeedStudents();

            var result = _controller.Index(null, null, "Carson", 5) as ViewResult;

            var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_SetsViewBagSortParams()
        {
            SeedStudents();

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_WithSortOrderSet_ViewBagNameSortParmIsEmpty()
        {
            SeedStudents();

            _controller.Index("name_desc", null, null, null);

            Assert.Equal("", _controller.ViewBag.NameSortParm);
        }

        // ── Details ──

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            SeedStudents();
            var studentId = _context.Students.First().ID;

            var result = _controller.Details(studentId) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(studentId, model.ID);
            Assert.Equal("Alexander", model.LastName);
        }

        // ── Create GET ──

        [Fact]
        public void Create_Get_ReturnsViewWithStudentHavingTodaysDate()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate.Date);
        }

        // ── Create POST ──

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.Parse("2024-01-15")
            };

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Students);
            Assert.Equal("User", _context.Students.First().LastName);
        }

        [Fact]
        public void Create_Post_MinValueDate_ReturnsViewWithError()
        {
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
            Assert.Empty(_context.Students);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "",
                EnrollmentDate = DateTime.Parse("2024-01-15")
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Students);
        }

        // ── Edit GET ──

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            SeedStudents();
            var student = _context.Students.First();

            var result = _controller.Edit(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
        }

        // ── Edit POST ──

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            SeedStudents();
            var student = _context.Students.First();
            _context.Entry(student).State = EntityState.Detached;

            var updated = new Student
            {
                ID = student.ID,
                FirstMidName = "Updated",
                LastName = "Name",
                EnrollmentDate = DateTime.Parse("2024-06-01")
            };

            var result = _controller.Edit(updated);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_MinValueDate_ReturnsViewWithError()
        {
            SeedStudents();
            var student = _context.Students.First();
            _context.Entry(student).State = EntityState.Detached;

            var updated = new Student
            {
                ID = student.ID,
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Edit(updated) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        // ── Delete GET ──

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Delete(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithStudent()
        {
            SeedStudents();
            var student = _context.Students.First();

            var result = _controller.Delete(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(student.ID, model.ID);
        }

        // ── DeleteConfirmed ──

        [Fact]
        public void DeleteConfirmed_RemovesStudentAndRedirects()
        {
            SeedStudents();
            var student = _context.Students.First();

            var result = _controller.DeleteConfirmed(student.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Equal(2, _context.Students.Count());
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _envMock;
        private readonly Mock<ILogger<CoursesController>> _loggerMock;
        private readonly string _tempWebRoot;

        public CoursesControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);

            _tempWebRoot = Path.Combine(Path.GetTempPath(), "CoursesTest_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempWebRoot);

            _envMock = new Mock<IWebHostEnvironment>();
            _envMock.Setup(e => e.WebRootPath).Returns(_tempWebRoot);

            _loggerMock = new Mock<ILogger<CoursesController>>();

            _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempWebRoot))
            {
                try { Directory.Delete(_tempWebRoot, true); } catch { }
            }
        }

        private Department SeedDepartment()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01")
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(Department dept = null)
        {
            dept ??= SeedDepartment();
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        private Mock<IFormFile> CreateMockFile(string fileName, long length, byte[] content = null)
        {
            content ??= new byte[length];
            var mock = new Mock<IFormFile>();
            mock.Setup(f => f.FileName).Returns(fileName);
            mock.Setup(f => f.Length).Returns(length);
            mock.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s => s.Write(content, 0, content.Length));
            return mock;
        }

        // ── Index ──

        [Fact]
        public void Index_ReturnsCoursesList()
        {
            var dept = SeedDepartment();
            SeedCourse(dept);

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.Single(model);
            Assert.Equal("Chemistry", model[0].Title);
        }

