namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;
        private readonly NotificationService _notificationService;

        public NotificationsControllerTests()
        {
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: Guid.NewGuid().ToString())
                .Options;
            _context = new SchoolContext(options);
            _controller = new NotificationsController(_context);
            _notificationService = new NotificationService();

            // Drain the shared static queue
            while (_notificationService.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain after test
            while (_notificationService.ReceiveNotification() != null) { }
            _notificationService.Dispose();
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var data = result.Value;
            Assert.NotNull(data);
            // Check via dynamic / reflection
            var successProp = data.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(data));
            var countProp = data.GetType().GetProperty("count");
            Assert.Equal(0, (int)countProp.GetValue(data));
        }

        [Fact]
        public void GetNotifications_WithItems_ReturnsNotifications()
        {
            // Enqueue items via the static queue
            _notificationService.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
            _notificationService.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

            var result = _controller.GetNotifications();

            var data = result.Value;
            var countProp = data.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(data);
            Assert.True(count >= 1); // at least one dequeued (static queue may have others)
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            // Enqueue 15 items
            for (int i = 0; i < 15; i++)
            {
                _notificationService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            var result = _controller.GetNotifications();

            var data = result.Value;
            var countProp = data.GetType().GetProperty("count");
            var count = (int)countProp.GetValue(data);
            Assert.True(count <= 10, $"Expected at most 10 but got {count}");
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccessJson()
        {
            var result = _controller.MarkAsRead(1);

            Assert.NotNull(result);
            var data = result.Value;
            var successProp = data.GetType().GetProperty("success");
            Assert.True((bool)successProp.GetValue(data));
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        private IQueryable<string> CreateSource(int count)
        {
            return Enumerable.Range(1, count).Select(i => $"Item{i}").AsQueryable();
        }

        // ── Constructor ──

        [Fact]
        public void Constructor_SetsPageIndexAndTotalPages()
        {
            var items = new List<string> { "A", "B" };

            var list = new PaginatedList<string>(items, 20, 2, 5);

            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(20/5) = 4
            Assert.Equal(2, list.Count);
            Assert.Equal("A", list[0]);
            Assert.Equal("B", list[1]);
        }

        [Fact]
        public void Constructor_SinglePage_TotalPagesIs1()
        {
            var items = new List<int> { 1, 2, 3 };

            var list = new PaginatedList<int>(items, 3, 1, 10);

            Assert.Equal(1, list.TotalPages);
            Assert.Equal(1, list.PageIndex);
        }

        [Fact]
        public void Constructor_CountNotDivisibleByPageSize_RoundsUp()
        {
            var items = new List<int> { 1 };

            var list = new PaginatedList<int>(items, 11, 1, 5);

            Assert.Equal(3, list.TotalPages); // ceil(11/5) = 3
        }

        // ── HasPreviousPage / HasNextPage ──

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

            Assert.False(list.HasNextPage); // TotalPages = 2, PageIndex = 2
        }

        [Fact]
        public void HasNextPage_FirstPageOfMany_ReturnsTrue()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

            Assert.True(list.HasNextPage); // TotalPages = 2, PageIndex = 1
        }

        [Fact]
        public void HasPreviousAndNextPage_MiddlePage_BothTrue()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 30, 2, 10);

            Assert.True(list.HasPreviousPage);
            Assert.True(list.HasNextPage);
        }

        // ── Create ──

        [Fact]
        public void Create_FirstPage_ReturnsCorrectSlice()
        {
            var source = CreateSource(25);

            var result = PaginatedList<string>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal("Item1", result[0]);
            Assert.Equal("Item10", result[9]);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages); // ceil(25/10) = 3
        }

        [Fact]
        public void Create_SecondPage_SkipsFirstPageItems()
        {
            var source = CreateSource(25);

            var result = PaginatedList<string>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal("Item11", result[0]);
            Assert.Equal("Item20", result[9]);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var source = CreateSource(25);

            var result = PaginatedList<string>.Create(source, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal("Item21", result[0]);
            Assert.Equal("Item25", result[4]);
        }

        [Fact]
        public void Create_SinglePage_HasNoNavigation()
        {
            var source = CreateSource(5);

            var result = PaginatedList<string>.Create(source, 1, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmpty()
        {
            var source = Enumerable.Empty<string>().AsQueryable();

            var result = PaginatedList<string>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.Equal(1, result.PageIndex);
        }
    }
}

