using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain any leftover items from the static queue
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain after each test to avoid cross-test pollution
            while (_sut.ReceiveNotification() != null) { }
            _sut.Dispose();
        }

        // ── SendNotification + ReceiveNotification round-trip ──

        [Fact]
        public void SendNotification_Create_ProducesCorrectMessage()
        {
            _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("New Student 'John Doe' has been created", notification.Message);
            Assert.Equal("System", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_Update_ProducesCorrectMessage()
        {
            _sut.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
            Assert.Equal("UPDATE", notification.Operation);
        }

        [Fact]
        public void SendNotification_Delete_ProducesCorrectMessage()
        {
            _sut.SendNotification("Department", "7", "Engineering", EntityOperation.DELETE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
            Assert.Equal("DELETE", notification.Operation);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            _sut.SendNotification("Student", "99", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithNullDisplayName_UsesIdInMessage()
        {
            _sut.SendNotification("Student", "99", null, EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 99) has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithUserName_SetsCreatedBy()
        {
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "admin@test.com");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("admin@test.com", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToApproximatelyNow()
        {
            var before = DateTime.Now;
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            var after = DateTime.Now;

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, after);
        }

        // ── ReceiveNotification ──

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_FifoOrder()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void ReceiveNotification_DequeuesItem_SecondCallReturnsNull()
        {
            _sut.SendNotification("X", "1", EntityOperation.CREATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Null(second);
        }

        // ── Queue cap enforcement ──

        [Fact]
        public void SendNotification_ExceedingMaxQueueLength_OldestItemsRemoved()
        {
            // Enqueue 510 items; the cap is 500 so the oldest should be trimmed
            for (int i = 0; i < 510; i++)
            {
                _sut.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Count remaining items
            int count = 0;
            while (_sut.ReceiveNotification() != null) count++;

            Assert.True(count <= 500, $"Expected at most 500 items but found {count}");
        }

        // ── GenerateMessage (tested indirectly) ──

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Course 'Math' has been created")]
        [InlineData(EntityOperation.UPDATE, "Course 'Math' has been updated")]
        [InlineData(EntityOperation.DELETE, "Course 'Math' has been deleted")]
        public void SendNotification_GenerateMessage_CorrectTextForEachOperation(EntityOperation op, string expected)
        {
            _sut.SendNotification("Course", "1", "Math", op);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal(expected, notification.Message);
        }

        [Fact]
        public void SendNotification_WhitespaceDisplayName_UsesIdFallback()
        {
            _sut.SendNotification("Student", "5", "   ", EntityOperation.DELETE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 5) has been deleted", notification.Message);
        }

        // ── Dispose ──

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());

            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _sut.MarkAsRead(1));

            Assert.Null(exception);
        }
    }
}

using System;
